$articleIds = [];
$offset = 0;
$limit = 12;
do {
    $listResult = $tools->call('cms_list_articles', ['offset'=>$offset, 'limit'=>$limit]);
    if (!isset($listResult->items) || !is_array($listResult->items)) {
        break; // safety
    }
    foreach ($listResult->items as $item) {
        $articleIds[] = $item->id;
    }
    $next = $listResult->next_offset ?? null;
    if ($next === null) {
        $offset = null;
    } else {
        $offset = $next;
    }
} while ($offset !== null);

$totalArticles = count($articleIds);
$articles = [];
for ($i=0;$i<$totalArticles;$i+=12) {
    $batch = array_slice($articleIds, $i, 12);
    $metaResult = $tools->call('cms_get_articles', ['ids'=>$batch]);
    if (!isset($metaResult->items) || !is_array($metaResult->items)) continue;
    foreach ($metaResult->items as $art) {
        $articles[$art->id] = $art;
    }
}

$imageIds = [];
foreach ($articles as $art) {
    if (isset($art->image_id) && $art->image_id !== null) {
        $imageIds[$art->image_id] = true;
    }
}
$imageIdList = array_keys($imageIds);
$mediaMap = [];
for ($i=0;$i<count($imageIdList);$i+=12) {
    $batch = array_slice($imageIdList, $i, 12);
    $mediaResult = $tools->call('cms_get_media', ['ids'=>$batch]);
    if (!isset($mediaResult->items) || !is_array($mediaResult->items)) continue;
    foreach ($mediaResult->items as $m) {
        $mediaMap[$m->id] = $m;
    }
}

$findings = [];
foreach ($articles as $id=>$art) {
    $issues = [];
    if (!isset($art->meta_description) || $art->meta_description === '') {
        $issues[] = 'missing_description';
    }
    if (isset($art->image_id) && $art->image_id !== null) {
        $media = $mediaMap[$art->image_id] ?? null;
        if ($media && (!isset($media->alt) || $media->alt === '')) {
            $issues[] = 'missing_alt';
        }
    }
    if (count($issues) > 0) {
        $findings[] = (object)[
            'id' => $id,
            'title' => $art->title,
            'issues' => $issues
        ];
    }
}
// sort findings by id
usort($findings, function($a,$b){return $a->id <=> $b->id;});
return (object)[
    'audited' => $totalArticles,
    'findings' => $findings
];

