$allArticles = [];
$offset = 0;
$limit = 12;
do {
    $resp = $tools->call('cms_list_articles', ['offset'=>$offset, 'limit'=>$limit]);
    if (!isset($resp->items) || !is_array($resp->items)) { break; }
    foreach ($resp->items as $item) {
        $allArticles[$item->id] = $item->title;
    }
    $next = $resp->next_offset ?? null;
    if ($next === null) {
        $offset = null;
    } else {
        $offset = $next;
    }
} while ($offset !== null);
$articleIds = array_keys($allArticles);
$articleMeta = [];
for ($i = 0; $i < count($articleIds); $i += 12) {
    $batch = array_slice($articleIds, $i, 12);
    $resp = $tools->call('cms_get_articles', ['ids'=>$batch]);
    if (!isset($resp->items) || !is_array($resp->items)) { continue; }
    foreach ($resp->items as $item) {
        $articleMeta[$item->id] = [
            'title' => $item->title,
            'meta_description' => $item->meta_description ?? '',
            'image_id' => $item->image_id ?? null
        ];
    }
}
$imageIdSet = [];
foreach ($articleMeta as $am) {
    $img = $am['image_id'];
    if ($img !== null) {
        $imageIdSet[$img] = true;
    }
}
$imageIds = array_keys($imageIdSet);
$mediaMap = [];
for ($i = 0; $i < count($imageIds); $i += 12) {
    $batch = array_slice($imageIds, $i, 12);
    $resp = $tools->call('cms_get_media', ['ids'=>$batch]);
    if (!isset($resp->items) || !is_array($resp->items)) { continue; }
    foreach ($resp->items as $item) {
        $mediaMap[$item->id] = $item->alt ?? '';
    }
}
$findings = [];
foreach ($articleMeta as $id => $am) {
    $issues = [];
    if (trim($am['meta_description']) === '') {
        $issues[] = 'missing_description';
    }
    $img = $am['image_id'];
    if ($img !== null && array_key_exists($img, $mediaMap)) {
        if (trim($mediaMap[$img]) === '') {
            $issues[] = 'missing_alt';
        }
    }
    if (!empty($issues)) {
        $findings[] = ['id'=>$id, 'title'=>$am['title'], 'issues'=>$issues];
    }
}
usort($findings, function($a,$b){return $a['id'] <=> $b['id'];});
$audited = count($articleIds);
return ['audited'=>$audited, 'findings'=>$findings];

